<?php require __DIR__.'/../config/config.php';require __DIR__.'/../includes/functions.php';$status=$_GET['status']??'';$sql="SELECT p.id_pinjam,a.nama,b.judul,p.tgl_pinjam,p.tgl_kembali,p.status,CASE WHEN p.status='dipinjam' THEN GREATEST(DATEDIFF(CURDATE(),p.tgl_pinjam)-7,0) ELSE 0 END hari_terlambat FROM peminjaman p INNER JOIN anggota a ON a.id_anggota=p.id_anggota INNER JOIN buku b ON b.id_buku=p.id_buku";$params=[];if(in_array($status,['dipinjam','kembali'],true)){$sql.=' WHERE p.status=?';$params[]=$status;}$sql.=' ORDER BY p.tgl_pinjam DESC,p.id_pinjam DESC';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$title='Data Peminjaman';require __DIR__.'/../includes/header.php';?><div class="d-flex justify-content-between mb-3"><h3>Data Peminjaman</h3><a href="tambah.php" class="btn btn-success">+ Pinjam Buku</a></div><form class="mb-3 d-flex gap-2 align-items-center"><label>Status</label><select name="status" class="form-select w-auto" onchange="this.form.submit()"><option value="">Semua</option><option value="dipinjam" <?=$status==='dipinjam'?'selected':''?>>Dipinjam</option><option value="kembali" <?=$status==='kembali'?'selected':''?>>Kembali</option></select></form><div class="table-responsive"><table class="table table-bordered table-striped bg-white"><thead class="table-light"><tr><th>ID</th><th>Anggota</th><th>Judul Buku</th><th>Tgl Pinjam</th><th>Tgl Kembali</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><?=e($p['id_pinjam'])?></td><td><?=e($p['nama'])?></td><td><?=e($p['judul'])?></td><td><?=e($p['tgl_pinjam'])?></td><td><?=e($p['tgl_kembali']??'-')?></td><td><?php if($p['status']==='kembali')echo '<span class="badge bg-success">kembali</span>';elseif($p['hari_terlambat']>0)echo '<span class="badge bg-danger">terlambat '.e($p['hari_terlambat']).' hari</span>';else echo '<span class="badge bg-warning text-dark">dipinjam</span>';?></td><td><?php if($p['status']==='dipinjam')?><form class="d-inline" method="post" action="kembalikan.php"><input type="hidden" name="id" value="<?=e($p['id_pinjam'])?>"><button class="btn btn-sm btn-primary" <?=$p['status']!=='dipinjam'?'disabled':''?>>Kembalikan</button></form><form class="d-inline" method="post" action="hapus.php" onsubmit="return confirm('Hapus transaksi?')"><input type="hidden" name="id" value="<?=e($p['id_pinjam'])?>"><button class="btn btn-sm btn-danger">Hapus</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center">Belum ada transaksi.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
